import type { APIRoute } from "astro";
import { loadDocs } from "../lib/docs";
import { styleToClass } from "../lib/render";

// Shiki's token colours as classes, so the CSP can be `style-src 'self'`.
// Rendering every document first means the registry is complete, whatever
// order Astro builds the routes in.
export const GET: APIRoute = async () => {
  await loadDocs();
  const css =
    "/* Generated by transformerStyleToClass. */\n" +
    styleToClass.getCSS().replace(/}/g, "}\n");
  return new Response(css, { headers: { "Content-Type": "text/css; charset=utf-8" } });
};
